package nir.com.neonvegasslots;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.graphics.*;import java.lang.reflect.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE) public class SpecialRuntimeTest {
 static Object get(Object o,String name)throws Exception{Field f=SlotsView.class.getDeclaredField(name);f.setAccessible(true);return f.get(o);} static void call(SlotsView v,String name)throws Exception{Method m=SlotsView.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(v);}
 @Test public void defaultRemainsDisabled(){assertFalse(SpecialFeature.ENABLED);assertFalse(new SlotsView(RuntimeEnvironment.getApplication()).usesSpecialFeature());}
 @Test public void pendingResultSurvivesFullGameSerializeAndCreditsOnce()throws Exception{SlotsView first=new SlotsView(RuntimeEnvironment.getApplication(),true);call(first,"spin");String save=first.serialize();SpecialFeature.State pending=(SpecialFeature.State)get(first,"specialState");assertTrue(pending.pending);SlotsView reopened=new SlotsView(RuntimeEnvironment.getApplication(),true);reopened.restore(save);assertTrue(reopened.isSpinning());assertEquals(java.util.Arrays.deepToString(pending.grid),java.util.Arrays.deepToString((int[][])get(reopened,"grid")));long debitBalance=reopened.getBalance();call(reopened,"finishSpin");assertEquals(debitBalance+pending.award,reopened.getBalance());long once=reopened.getBalance();call(reopened,"finishSpin");assertEquals(once,reopened.getBalance());SlotsView third=new SlotsView(RuntimeEnvironment.getApplication(),true);third.restore(reopened.serialize());assertFalse(third.isSpinning());assertEquals(once,third.getBalance());}
 @Test public void freeSpinsRetainStakeNoDebitOrExtraProgressionGrants()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication(),true);call(v,"spin");SpecialFeature.State state=(SpecialFeature.State)get(v,"specialState");int[][] grid=(int[][])get(v,"grid");for(int[] row:grid)java.util.Arrays.fill(row,7);state.award=0;call(v,"finishSpin");assertEquals(5,v.freeSpinsRemaining());long xp=(long)get(v,"xp"),paid=v.getSpinsDone();Field moment=SlotsView.class.getDeclaredField("bonusMomentUntil");moment.setAccessible(true);moment.setLong(v,0);v.addCoins(300);long before=v.getBalance();int idx=v.betIdx();v.betStep(1);assertEquals(idx,v.betIdx());call(v,"spin");assertEquals(before,v.getBalance());assertEquals(10,state.stake);assertTrue(state.free);assertEquals(xp,(long)get(v,"xp"));assertEquals(0,SpecialFeature.scatterReels((int[][])get(v,"grid"),5));call(v,"finishSpin");assertEquals(paid,v.getSpinsDone());SlotsView resumed=new SlotsView(RuntimeEnvironment.getApplication(),true);resumed.restore(v.serialize());assertEquals(4,resumed.freeSpinsRemaining());}
 @Test public void enabledRenderDoesNotMutateSampledGrid()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication(),true);v.layout(0,0,1080,1500);call(v,"spin");String before=java.util.Arrays.deepToString((int[][])get(v,"grid"));v.draw(new Canvas(Bitmap.createBitmap(1080,1500,Bitmap.Config.ARGB_8888)));assertEquals(before,java.util.Arrays.deepToString((int[][])get(v,"grid")));}
 @Test public void bonusMomentPreview()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication(),true);v.layout(0,0,1080,1500);call(v,"spin");SpecialFeature.State state=(SpecialFeature.State)get(v,"specialState");int[][] grid=(int[][])get(v,"grid");for(int[] row:grid)java.util.Arrays.fill(row,2);grid[0][0]=7;grid[1][2]=7;grid[2][4]=7;state.award=SpecialFeature.evaluate(grid,10);call(v,"finishSpin");Bitmap b=Bitmap.createBitmap(1080,1500,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);v.draw(canvas);Paint label=new Paint(3);label.setColor(0xEE151020);canvas.drawRect(0,0,1080,44,label);label.setColor(Color.WHITE);label.setTextSize(27);canvas.drawText("DISABLED CANDIDATE - SYNTHETIC RENDER",160,31,label);try(java.io.FileOutputStream out=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-bonus-runtime-candidate.png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void failedCommitBlocksFurtherTransactionsAndKeepsDurableSnapshotRecoverable()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication(),true);String before=v.serialize();v.setListener(new SlotsView.Listener(){public void onOutOfCoins(){}public void onSpinComplete(int s,long w,long b){}public void onBigWin(long w,long b){}public void onLevelUp(int l,long r){}public void saveState(){}public boolean saveSpecialState(String snapshot){return false;}});try{call(v,"spin");fail("must fail closed");}catch(java.lang.reflect.InvocationTargetException expected){assertTrue(expected.getCause() instanceof IllegalStateException);}assertTrue((boolean)get(v,"saveFault"));long blocked=v.getBalance();try{v.addCoins(300);fail("coin delivery must not silently disappear");}catch(IllegalStateException expected){}assertEquals(blocked,v.getBalance());call(v,"spin");assertEquals(blocked,v.getBalance());SlotsView recovered=new SlotsView(RuntimeEnvironment.getApplication(),true);recovered.restore(before);assertEquals(500,recovered.getBalance());assertFalse(recovered.isSpinning());}
 @Test public void fullCabinetPreview()throws Exception{SlotsView v=new SlotsView(RuntimeEnvironment.getApplication(),true);v.layout(0,0,1080,1500);int[][] grid=(int[][])get(v,"grid");grid[0][1]=6;grid[1][3]=7;grid[2][4]=7;Bitmap b=Bitmap.createBitmap(1080,1500,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);v.draw(canvas);Paint label=new Paint(3);label.setColor(0xEE151020);canvas.drawRect(0,0,1080,44,label);label.setColor(Color.WHITE);label.setTextSize(27);canvas.drawText("DISABLED CANDIDATE - SYNTHETIC RENDER",160,31,label);try(java.io.FileOutputStream out=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-special-runtime-candidate.png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
}
